            //---------------------------------------------------------------------
            function dotaz(otazka, that) {
                return that.dialogs.confirm(otazka).createDialogPromise("yes");
            }
            Dialogs.dotaz = dotaz;
            function GPapUkonceni(options) {
                var that = options.that;
                var seznam = options.seznam;
                var l_pocet = seznam.length;
                var param = options.param;
                let stru = { seznam: seznam, akce: "ukonceni", param: param, odpoved: null };
                var zkratka = "VZ";
                switch (options.agenda) {
                    case "VFP":
                        zkratka = "DT";
                        break;
                    case "EPO":
                        zkratka = "PO";
                        break;
                }
                //RC 26600295 : Opravdu chcete ukončit označené případy {0}? ;Po ukončení bude znemožněna jakákoliv manipulace s dokumenty.
                //RC 26600296 : Opravdu chcete ukončit případ {0}?; Po ukončení bude znemožněna jakákoliv manipulace s dokumentem.
                var otazka = ((l_pocet > 1) ? "jres:26600295" : "jres:26600296").format(zkratka);
                return Pap.Dialogs.dotaz(otazka, that)
                    .then(() => {
                    if (l_pocet > 1) { // hromadné
                        var otazka2 = "jres:26600297"; //RC 26600297 : Případ bude uzavřen i tehdy, když nebude prozatím vázán na doklady realizující nasmlouvání prostředků.; Má-li neuvolněné prostředky v daném období, volné prostředky uvolní a provede úpravu schválené částky na případu.;Chcete-li zvolit jiný postup proveďte akci na detailu, kde budete vyzváni k bližší specifikaci vašich požadavků.;; Chcete pokračovat?;
                        return Pap.Dialogs.dotaz(otazka2, that)
                            .then(() => {
                            return that.isl.PapUkonceni.ukonceni(stru).get()
                                .then(function (retVal) {
                                if (retVal.data.hlas != "") {
                                    that.dialogs.warning("jres:26600129", retVal.data.hlas); //RC 26600129 : Upozornění
                                }
                                return retVal.data.ok ? $.Deferred().resolve().promise() : $.Deferred().reject().promise();
                            }, //fail vetev, nemusi zde byt, za predpokladu, ze pap.dialogs.dotaz vraci bez vysledku reject promise 
                            () => {
                                return $.Deferred().reject().promise();
                            });
                        }, 
                        //fail vetev, nemusi zde byt, za predpokladu, ze pap.dialogs.dotaz vraci bez vysledku reject promise 
                        () => {
                            return $.Deferred().reject().promise();
                        });
                    }
                    else { //jednotlivé - jako v detailu
                        stru.odpoved = [0, 0, 0];
                        return that.isl.PapUkonceni.ukonceni(stru).get()
                            .then(function (retVal) {
                            var def = $.Deferred();
                            if (retVal.data.dotaz === "") {
                                def.resolve(retVal.data);
                            }
                            else { // dotaz, co dělat když jsou nenavázané prostředky
                                Pap.Dialogs.dotaz(retVal.data.dotaz, that)
                                    .then(() => {
                                    stru.odpoved[0] = 1;
                                    return that.isl.PapUkonceni.ukonceni(stru).get();
                                })
                                    .then(function (returnVal) {
                                    let def1 = $.Deferred();
                                    if (returnVal.data.dotaz === "") {
                                        def1.resolve(returnVal.data);
                                    }
                                    else { //dotaz, zda uvolnit prostředky
                                        Pap.Dialogs.dotaz(returnVal.data.dotaz, that)
                                            .then(() => {
                                            stru.odpoved[1] = 1;
                                            Pap.Dialogs.dotaz(returnVal.data.hlas, that) // dotaz zda upravit castku;
                                                .then(() => {
                                                stru.odpoved[2] = 1;
                                            }, () => {
                                                stru.odpoved[2] = -1;
                                            }).always(() => {
                                                return that.isl.PapUkonceni.ukonceni(stru).get()
                                                    .then(function (reVal) { def1.resolve(reVal.data); });
                                            });
                                        }, () => {
                                            stru.odpoved[1] = -1;
                                            stru.odpoved[2] = -1;
                                            return that.isl.PapUkonceni.ukonceni(stru).get()
                                                .then(function (reVal) { def1.resolve(reVal.data); });
                                        });
                                    }
                                    return def1.promise();
                                }, () => {
                                    def.reject(); //nepokracuji -nenavazane prostredky
                                })
                                    .then((rVal) => {
                                    def.resolve(rVal);
                                }, () => {
                                    def.reject();
                                });
                            }
                            return def.promise();
                        }).
                            then((retVal) => {
                            if (retVal.hlas != "") {
                                that.dialogs.warning("jres:26600129", retVal.hlas); //RC 26600129 : Upozornění
                            }
                            return (retVal.ok) ? $.Deferred().resolve().promise() : $.Deferred().reject().promise();
                        });
                    }
                });
            }
            Dialogs.GPapUkonceni = GPapUkonceni;
            ////---------------------------------------------------------------------
            function GPapOdUkonceni(options) {
                var that = options.that;
                var seznam = options.seznam;
                var l_pocet = seznam.length;
                var seznam = options.seznam;
                var param = options.param;
                var zkratka = "VZ";
                if (options.agenda == "VFP")
                    zkratka = "DT";
                else if (options.agenda == "EPO")
                    zkratka = "PO";
                var otazka = "";
                if (l_pocet > 1)
                    otazka = "jres:26600298".replace("{0}", zkratka); //RC 26600298 : Opravdu chcete zrušit ukončení označených případů {0}?
                else
                    otazka = "jres:26600299".replace("{0}", zkratka); //RC 26600299 : Opravdu chcete zrušit ukončení případu {0}?
                return Pap.Dialogs.dotaz(otazka, that)
                    .then(() => {
                    var stru = { seznam: seznam, akce: "odukonceni", param: param };
                    return that.isl.PapUkonceni.ukonceni(stru).get()
                        .then(function (retVal) {
                        if (retVal.data.hlas != "") {
                            that.dialogs.warning("jres:26600129", retVal.data.hlas); //RC 26600129 : Upozornění
                        }
                        if (retVal.data.ok)
                            return $.Deferred().resolve().promise();
                        else
                            return $.Deferred().reject().promise();
                    })
                        .fail(function () { return $.Deferred().reject().promise(); });
                })
                    .fail(function () { return $.Deferred().reject().promise(); });
            }
            Dialogs.GPapOdUkonceni = GPapOdUkonceni;
