                columns(l_col) {
                    if (this.nameTable == "evzskpu" || this.nameTable == "vfpsobl" || this.nameTable == "rzaskpu") {
                        this.NaplnColKpuObl(l_col);
                    }
                    else if (this.nameTable == "evzsaza")
                        this.NaplnColAza(l_col);
                    else if (this.nameTable == "vfpctdg")
                        this.NaplnColTdg(l_col);
                    else if (this.nameTable == "evzsoko")
                        this.NaplnColOko(l_col);
                    else if (this.nameTable == "evzskdn")
                        this.NaplnColKdn(l_col);
                    else if (this.nameTable == "rzasleg")
                        this.NaplnColLeg(l_col);
                    else if (this.nameTable == "mzacsou")
                        this.NaplnColSou(l_col);
                    else if (this.nameTable == "mzactyd")
                        this.NaplnColTyd(l_col);
                    else if (this.nameTable == "rzacrez")
                        this.NaplnColRez(l_col);
                    else if (this.nameTable == "rzacpru")
                        this.NaplnColPru(l_col);
                    else if (this.nameTable == "rzacvri")
                        this.NaplnColVri(l_col);
                    else if (this.nameTable == "rzaczpr")
                        this.NaplnColZpr(l_col);
                    else if (this.nameTable == "rzascfp")
                        this.NaplnColCfp(l_col);
                    return l_col;
                }
