                    if (typeof ixs_fun_akt === "undefined" || ixs_fun_akt === null /* || ixs_fun_akt === null*/) {
                        content.dialogs.warning("jres:26600564") //RC 30250682 :  Není vyplněn cíl předání
                            .on("close", () => def.reject(false));
                        return def.promise();
                    }
                    //var vybraneDoklady = Gordic.Eko.Grid.checkedRows<Gordic.Uct.Interface.GRozVybranyDokladDto>(that.$grid, true);
                    if (typeof vybraneDoklady === "undefined" || vybraneDoklady == null || vybraneDoklady.length === 0) {
                        content.dialogs.alert("jres:26600565"); //RC 26600565 : Nebyly vybrány žádné doklady k přeevidenci
                        return def.reject().promise();
                    }
                    let result = {
                        Seznam: vybraneDoklady,
                        IxsFunVyriz: ixs_fun_vyriz,
                        IxsFun: ixs_fun_akt,
                        Duvod: duvod
                    };
                    return def.resolve(result).promise();
